export class AccountDraftPanel {
  customerCode: string = ''
  submitDraft(): void {
    if (this.customerCode.trim().length === 0) {
      promptAction.showToast({ message: 'A value is required' })
      return
    }
    this.dispatchDraft(this.customerCode)
  }
  private dispatchDraft(value: string): void {
    console.info('Account draft dispatched', value)
  }
}

